class Solution {
    vector<pair<int,int>> topTwo(const unordered_map<int,int>& f) {
        vector<pair<int,int>> a={{0,-1},{0,-2}};
        for(auto &p:f) {
            pair<int,int> cur={p.second,p.first};
            if(cur.first>a[0].first){a[1]=a[0];a[0]=cur;}
            else if(cur.first>a[1].first) a[1]=cur;
        }
        return a;
    }
public:
    int minimumOperations(vector<int>& nums) {
        unordered_map<int,int> even,odd;
        for(int i=0;i<(int)nums.size();++i) ++(i%2?odd:even)[nums[i]];
        auto a=topTwo(even),b=topTwo(odd);
        int keep=(a[0].second!=b[0].second)?a[0].first+b[0].first:
                 max(a[0].first+b[1].first,a[1].first+b[0].first);
        return (int)nums.size()-keep;
    }
};
